const definitionError = { name: "TypeError", message: "PRESENTATION_DEFINITION_INVALID" };
const copyError = { name: "TypeError", message: "PRESENTATION_COPY_INVALID" };

export const invalidPresentationCases = [
  { name: "unknown outer fields", mutate: (value) => { value.unexpected = true; }, error: definitionError },
  { name: "unknown scene fields", mutate: (value) => { value.scenes[0].unexpected = true; }, error: definitionError },
  { name: "unknown palette fields", mutate: (value) => { value.palettes[0].unexpected = true; }, error: definitionError },
  { name: "unknown base color fields", mutate: (value) => { value.palettes[0].baseColors.unexpected = true; }, error: definitionError },
  { name: "unknown fragrance fields", mutate: (value) => { value.fragrances[0].unexpected = true; }, error: definitionError },
  { name: "unknown selector fields", mutate: (value) => { value.titleSelectors[0].unexpected = true; }, error: definitionError },
  { name: "unknown scene selector fields", mutate: (value) => { value.titleSelectors[0].fragranceScenes[0].unexpected = true; }, error: definitionError },
  { name: "50 selectors", mutate: (value) => { value.titleSelectors.pop(); }, error: definitionError },
  { name: "52 selectors", mutate: (value) => { value.titleSelectors.push(structuredClone(value.titleSelectors[0])); }, error: definitionError },
  { name: "duplicate title IDs", mutate: (value) => { value.titleSelectors[1].titleId = value.titleSelectors[0].titleId; }, error: definitionError },
  { name: "missing title IDs", mutate: (value) => { value.titleSelectors[0].titleId = "title-missing"; }, error: definitionError },
  { name: "missing palette IDs", mutate: (value) => { value.palettes.pop(); }, error: definitionError },
  { name: "duplicate palette IDs", mutate: (value) => { value.palettes[1].paletteId = value.palettes[0].paletteId; }, error: definitionError },
  { name: "orphan palette IDs", mutate: (value) => { value.palettes.push(structuredClone(value.palettes[0])); value.palettes.at(-1).paletteId = "palette-orphan"; }, error: definitionError },
  { name: "missing fragrance IDs", mutate: (value) => { value.fragrances.pop(); }, error: definitionError },
  { name: "duplicate fragrance IDs", mutate: (value) => { value.fragrances[1].fragranceId = value.fragrances[0].fragranceId; }, error: definitionError },
  { name: "orphan fragrance IDs", mutate: (value) => { value.fragrances.push({ ...value.fragrances[0], fragranceId: "fragrance-pause-orphan" }); }, error: definitionError },
  { name: "mismatched definition version", mutate: (value) => { value.presentationDefinitionVersion = "presentation-v2"; }, error: definitionError },
  { name: "mismatched palette version", mutate: (value) => { value.palettes[0].version = "presentation-v2"; }, error: definitionError },
  { name: "mismatched fragrance version", mutate: (value) => { value.fragrances[0].version = "presentation-v2"; }, error: definitionError },
  { name: "one alternative palette", mutate: (value) => { value.titleSelectors[0].alternativePaletteIds.pop(); }, error: definitionError },
  { name: "three alternative palettes", mutate: (value) => { value.titleSelectors[0].alternativePaletteIds.push("palette-extra"); }, error: definitionError },
  { name: "standard and alternative palette duplication", mutate: (value) => { value.titleSelectors[0].alternativePaletteIds[0] = "palette-default"; }, error: definitionError },
  { name: "alternative palette duplication", mutate: (value) => { value.titleSelectors[0].alternativePaletteIds[1] = value.titleSelectors[0].alternativePaletteIds[0]; }, error: definitionError },
  { name: "missing base colors", mutate: (value) => { delete value.palettes[0].baseColors.accent; }, error: definitionError },
  { name: "extra base colors", mutate: (value) => { value.palettes[0].baseColors.neutral = "#012345"; }, error: definitionError },
  { name: "malformed HEX colors", mutate: (value) => { value.palettes[0].baseColors.primary = "#abcdef"; }, error: definitionError },
  { name: "missing scenes", mutate: (value) => { value.scenes.pop(); }, error: definitionError },
  { name: "reordered scenes", mutate: (value) => { [value.scenes[0], value.scenes[1]] = [value.scenes[1], value.scenes[0]]; }, error: definitionError },
  { name: "duplicated scenes", mutate: (value) => { value.scenes[1].sceneId = "pause"; }, error: definitionError },
  { name: "one fragrance candidate", mutate: (value) => { value.titleSelectors[0].fragranceScenes[0].candidateFragranceIds.pop(); }, error: definitionError },
  { name: "three fragrance candidates", mutate: (value) => { value.titleSelectors[0].fragranceScenes[0].candidateFragranceIds.push("fragrance-pause-extra"); }, error: definitionError },
  { name: "fragrance scene mismatch", mutate: (value) => { value.fragrances[0].sceneId = "reset"; }, error: definitionError },
  { name: "share ID outside candidates", mutate: (value) => { value.titleSelectors[0].fragranceScenes[0].shareFragranceId = "fragrance-pause-outside"; }, error: definitionError },
  ...["answers", "score", "band", "characterColor", "replacementPaletteId", "recolor"].map((field) => ({
    name: `forbidden ${field} field`, mutate: (value) => { value.titleSelectors[0][field] = true; }, error: definitionError,
  })),
  { name: "forbidden product copy", mutate: (value) => { value.palettes[0].description = "Buy this product"; }, error: copyError },
  { name: "forbidden essential-oil copy", mutate: (value) => { value.fragrances[0].accordLabel = "Lavender essential oil"; }, error: copyError },
  { name: "forbidden usage copy", mutate: (value) => { value.fragrances[0].description = "Use 3 drops in a diffuser"; }, error: copyError },
  { name: "forbidden effect copy", mutate: (value) => { value.fragrances[0].description = "Improves your ability"; }, error: copyError },
];
